//-----------------------------------------------------------
// Function: Simple known-answer test for CFB mode, deciphering of every segment size (1,2,4,8,16,32,64,128 bits)
//-----------------------------------------------------------
// Author: Nguyen Hung Quan
// Website: http://nguyenquanicd.blogspot.com/
//-----------------------------------------------------------
// History:
// 2019.10.22 - First version (ECB)
// 2026.10.10 - Rewritten on top of tb/aes128_tb_common.svh: inputs are driven on the
//              falling clock edge (no race with the DUT), X in the output fails the
//              check (the old TB used '!=' and printed PASS for 'xxxx'), the
//              simulation ends with $finish and prints TEST_RESULT.
// Expected values come from NIST SP 800-38A F.3.x (segments 1, 8, 128) and tools/aes_ref.py (others)
// (generated by tools/gen_simple_tbs.py; do not edit by hand).
// Compile with the include directory tb/ (-Itb or +incdir+tb).
//-----------------------------------------------------------
`timescale 1ns/1ps
module tb_aes128_cfb_decipher;
  `include "aes128_tb_common.svh"
  localparam logic [127:0] KEY = 128'h2b7e151628aed2a6abf7158809cf4f3c;
  localparam logic [127:0] IV  = 128'h000102030405060708090a0b0c0d0e0f;
  logic [127:0] d;
  int lat;
  //One step: run the operation, compare under the mask and print a readable line
  task automatic step(input string label, input bit dec, input logic [3:0] m, input logic [3:0] seg,
                      input bit chain, input logic [127:0] iv_, input logic [127:0] din,
                      input logic [127:0] expv, input logic [127:0] msk);
    int f0;
    f0 = n_fail;
    run_op(dec, m, seg, chain, KEY, iv_, din, d, lat);
    check_eq(label, d, expv, msk);
    $display("----- %-22s data_in=%032h data_out=%032h %s", label, din, d, (n_fail == f0 && lat > 0) ? "PASS" : "FAIL");
  endtask
  //chain_en low for 2 clocks: the next operation starts a new stream
  task automatic new_stream;
    chain_en = 1'b0;
    tick(2);
  endtask
  initial begin
    repeat (4) @ (negedge clk);
    rst_n = 1'b1;
    repeat (2) @ (negedge clk);
    //CFB1 (NIST F.3.1/F.3.2)
    new_stream;
    step("CFB1 dec 1", 1'b1, M_CFB, 4'd0, 1'b1, IV, 128'h00000000000000000000000000000000, 128'h00000000000000000000000000000000, 128'h80000000000000000000000000000000);
    step("CFB1 dec 2", 1'b1, M_CFB, 4'd0, 1'b1, IV, 128'h80000000000000000000000000000000, 128'h80000000000000000000000000000000, 128'h80000000000000000000000000000000);
    step("CFB1 dec 3", 1'b1, M_CFB, 4'd0, 1'b1, IV, 128'h80000000000000000000000000000000, 128'h80000000000000000000000000000000, 128'h80000000000000000000000000000000);
    step("CFB1 dec 4", 1'b1, M_CFB, 4'd0, 1'b1, IV, 128'h00000000000000000000000000000000, 128'h00000000000000000000000000000000, 128'h80000000000000000000000000000000);
    step("CFB1 dec 5", 1'b1, M_CFB, 4'd0, 1'b1, IV, 128'h80000000000000000000000000000000, 128'h80000000000000000000000000000000, 128'h80000000000000000000000000000000);
    step("CFB1 dec 6", 1'b1, M_CFB, 4'd0, 1'b1, IV, 128'h00000000000000000000000000000000, 128'h00000000000000000000000000000000, 128'h80000000000000000000000000000000);
    step("CFB1 dec 7", 1'b1, M_CFB, 4'd0, 1'b1, IV, 128'h00000000000000000000000000000000, 128'h80000000000000000000000000000000, 128'h80000000000000000000000000000000);
    step("CFB1 dec 8", 1'b1, M_CFB, 4'd0, 1'b1, IV, 128'h00000000000000000000000000000000, 128'h80000000000000000000000000000000, 128'h80000000000000000000000000000000);
    step("CFB1 dec 9", 1'b1, M_CFB, 4'd0, 1'b1, IV, 128'h80000000000000000000000000000000, 128'h80000000000000000000000000000000, 128'h80000000000000000000000000000000);
    step("CFB1 dec 10", 1'b1, M_CFB, 4'd0, 1'b1, IV, 128'h00000000000000000000000000000000, 128'h80000000000000000000000000000000, 128'h80000000000000000000000000000000);
    step("CFB1 dec 11", 1'b1, M_CFB, 4'd0, 1'b1, IV, 128'h80000000000000000000000000000000, 128'h00000000000000000000000000000000, 128'h80000000000000000000000000000000);
    step("CFB1 dec 12", 1'b1, M_CFB, 4'd0, 1'b1, IV, 128'h80000000000000000000000000000000, 128'h00000000000000000000000000000000, 128'h80000000000000000000000000000000);
    step("CFB1 dec 13", 1'b1, M_CFB, 4'd0, 1'b1, IV, 128'h00000000000000000000000000000000, 128'h00000000000000000000000000000000, 128'h80000000000000000000000000000000);
    step("CFB1 dec 14", 1'b1, M_CFB, 4'd0, 1'b1, IV, 128'h00000000000000000000000000000000, 128'h00000000000000000000000000000000, 128'h80000000000000000000000000000000);
    step("CFB1 dec 15", 1'b1, M_CFB, 4'd0, 1'b1, IV, 128'h80000000000000000000000000000000, 128'h00000000000000000000000000000000, 128'h80000000000000000000000000000000);
    step("CFB1 dec 16", 1'b1, M_CFB, 4'd0, 1'b1, IV, 128'h80000000000000000000000000000000, 128'h80000000000000000000000000000000, 128'h80000000000000000000000000000000);
    //CFB8 (NIST F.3.7/F.3.8)
    new_stream;
    step("CFB8 dec 1", 1'b1, M_CFB, 4'd3, 1'b1, IV, 128'h3b000000000000000000000000000000, 128'h6b000000000000000000000000000000, 128'hff000000000000000000000000000000);
    step("CFB8 dec 2", 1'b1, M_CFB, 4'd3, 1'b1, IV, 128'h79000000000000000000000000000000, 128'hc1000000000000000000000000000000, 128'hff000000000000000000000000000000);
    step("CFB8 dec 3", 1'b1, M_CFB, 4'd3, 1'b1, IV, 128'h42000000000000000000000000000000, 128'hbe000000000000000000000000000000, 128'hff000000000000000000000000000000);
    step("CFB8 dec 4", 1'b1, M_CFB, 4'd3, 1'b1, IV, 128'h4c000000000000000000000000000000, 128'he2000000000000000000000000000000, 128'hff000000000000000000000000000000);
    step("CFB8 dec 5", 1'b1, M_CFB, 4'd3, 1'b1, IV, 128'h9c000000000000000000000000000000, 128'h2e000000000000000000000000000000, 128'hff000000000000000000000000000000);
    step("CFB8 dec 6", 1'b1, M_CFB, 4'd3, 1'b1, IV, 128'h0d000000000000000000000000000000, 128'h40000000000000000000000000000000, 128'hff000000000000000000000000000000);
    step("CFB8 dec 7", 1'b1, M_CFB, 4'd3, 1'b1, IV, 128'hd4000000000000000000000000000000, 128'h9f000000000000000000000000000000, 128'hff000000000000000000000000000000);
    step("CFB8 dec 8", 1'b1, M_CFB, 4'd3, 1'b1, IV, 128'h36000000000000000000000000000000, 128'h96000000000000000000000000000000, 128'hff000000000000000000000000000000);
    step("CFB8 dec 9", 1'b1, M_CFB, 4'd3, 1'b1, IV, 128'hba000000000000000000000000000000, 128'he9000000000000000000000000000000, 128'hff000000000000000000000000000000);
    step("CFB8 dec 10", 1'b1, M_CFB, 4'd3, 1'b1, IV, 128'hce000000000000000000000000000000, 128'h3d000000000000000000000000000000, 128'hff000000000000000000000000000000);
    step("CFB8 dec 11", 1'b1, M_CFB, 4'd3, 1'b1, IV, 128'h9e000000000000000000000000000000, 128'h7e000000000000000000000000000000, 128'hff000000000000000000000000000000);
    step("CFB8 dec 12", 1'b1, M_CFB, 4'd3, 1'b1, IV, 128'h0e000000000000000000000000000000, 128'h11000000000000000000000000000000, 128'hff000000000000000000000000000000);
    step("CFB8 dec 13", 1'b1, M_CFB, 4'd3, 1'b1, IV, 128'hd4000000000000000000000000000000, 128'h73000000000000000000000000000000, 128'hff000000000000000000000000000000);
    step("CFB8 dec 14", 1'b1, M_CFB, 4'd3, 1'b1, IV, 128'h58000000000000000000000000000000, 128'h93000000000000000000000000000000, 128'hff000000000000000000000000000000);
    step("CFB8 dec 15", 1'b1, M_CFB, 4'd3, 1'b1, IV, 128'h6a000000000000000000000000000000, 128'h17000000000000000000000000000000, 128'hff000000000000000000000000000000);
    step("CFB8 dec 16", 1'b1, M_CFB, 4'd3, 1'b1, IV, 128'h4f000000000000000000000000000000, 128'h2a000000000000000000000000000000, 128'hff000000000000000000000000000000);
    //CFB128 (NIST F.3.13/F.3.14)
    new_stream;
    step("CFB128 dec 1", 1'b1, M_CFB, 4'd7, 1'b1, IV, 128'h3b3fd92eb72dad20333449f8e83cfb4a, 128'h6bc1bee22e409f96e93d7e117393172a, ALL1);
    step("CFB128 dec 2", 1'b1, M_CFB, 4'd7, 1'b1, IV, 128'hc8a64537a0b3a93fcde3cdad9f1ce58b, 128'hae2d8a571e03ac9c9eb76fac45af8e51, ALL1);
    step("CFB128 dec 3", 1'b1, M_CFB, 4'd7, 1'b1, IV, 128'h26751f67a3cbb140b1808cf187a4f4df, 128'h30c81c46a35ce411e5fbc1191a0a52ef, ALL1);
    step("CFB128 dec 4", 1'b1, M_CFB, 4'd7, 1'b1, IV, 128'hc04b05357c5d1c0eeac4c66f9ff7f2e6, 128'hf69f2445df4f9b17ad2b417be66c3710, ALL1);
    //CFB2 (reference model)
    new_stream;
    step("CFB2 dec 1", 1'b1, M_CFB, 4'd1, 1'b1, IV, 128'h00000000000000000000000000000000, 128'h40000000000000000000000000000000, 128'hc0000000000000000000000000000000);
    step("CFB2 dec 2", 1'b1, M_CFB, 4'd1, 1'b1, IV, 128'h00000000000000000000000000000000, 128'h80000000000000000000000000000000, 128'hc0000000000000000000000000000000);
    step("CFB2 dec 3", 1'b1, M_CFB, 4'd1, 1'b1, IV, 128'h00000000000000000000000000000000, 128'h80000000000000000000000000000000, 128'hc0000000000000000000000000000000);
    step("CFB2 dec 4", 1'b1, M_CFB, 4'd1, 1'b1, IV, 128'h80000000000000000000000000000000, 128'hc0000000000000000000000000000000, 128'hc0000000000000000000000000000000);
    step("CFB2 dec 5", 1'b1, M_CFB, 4'd1, 1'b1, IV, 128'h80000000000000000000000000000000, 128'hc0000000000000000000000000000000, 128'hc0000000000000000000000000000000);
    step("CFB2 dec 6", 1'b1, M_CFB, 4'd1, 1'b1, IV, 128'h00000000000000000000000000000000, 128'h00000000000000000000000000000000, 128'hc0000000000000000000000000000000);
    step("CFB2 dec 7", 1'b1, M_CFB, 4'd1, 1'b1, IV, 128'hc0000000000000000000000000000000, 128'h00000000000000000000000000000000, 128'hc0000000000000000000000000000000);
    step("CFB2 dec 8", 1'b1, M_CFB, 4'd1, 1'b1, IV, 128'hc0000000000000000000000000000000, 128'h40000000000000000000000000000000, 128'hc0000000000000000000000000000000);
    //CFB4 (reference model)
    new_stream;
    step("CFB4 dec 1", 1'b1, M_CFB, 4'd2, 1'b1, IV, 128'h30000000000000000000000000000000, 128'h60000000000000000000000000000000, 128'hf0000000000000000000000000000000);
    step("CFB4 dec 2", 1'b1, M_CFB, 4'd2, 1'b1, IV, 128'h90000000000000000000000000000000, 128'hb0000000000000000000000000000000, 128'hf0000000000000000000000000000000);
    step("CFB4 dec 3", 1'b1, M_CFB, 4'd2, 1'b1, IV, 128'h20000000000000000000000000000000, 128'hc0000000000000000000000000000000, 128'hf0000000000000000000000000000000);
    step("CFB4 dec 4", 1'b1, M_CFB, 4'd2, 1'b1, IV, 128'h50000000000000000000000000000000, 128'h10000000000000000000000000000000, 128'hf0000000000000000000000000000000);
    step("CFB4 dec 5", 1'b1, M_CFB, 4'd2, 1'b1, IV, 128'h20000000000000000000000000000000, 128'hb0000000000000000000000000000000, 128'hf0000000000000000000000000000000);
    step("CFB4 dec 6", 1'b1, M_CFB, 4'd2, 1'b1, IV, 128'h60000000000000000000000000000000, 128'he0000000000000000000000000000000, 128'hf0000000000000000000000000000000);
    step("CFB4 dec 7", 1'b1, M_CFB, 4'd2, 1'b1, IV, 128'h70000000000000000000000000000000, 128'he0000000000000000000000000000000, 128'hf0000000000000000000000000000000);
    step("CFB4 dec 8", 1'b1, M_CFB, 4'd2, 1'b1, IV, 128'hf0000000000000000000000000000000, 128'h20000000000000000000000000000000, 128'hf0000000000000000000000000000000);
    //CFB16 (reference model)
    new_stream;
    step("CFB16 dec 1", 1'b1, M_CFB, 4'd4, 1'b1, IV, 128'h3b3f0000000000000000000000000000, 128'h6bc10000000000000000000000000000, 128'hffff0000000000000000000000000000);
    step("CFB16 dec 2", 1'b1, M_CFB, 4'd4, 1'b1, IV, 128'he4980000000000000000000000000000, 128'hbee20000000000000000000000000000, 128'hffff0000000000000000000000000000);
    step("CFB16 dec 3", 1'b1, M_CFB, 4'd4, 1'b1, IV, 128'h24de0000000000000000000000000000, 128'h2e400000000000000000000000000000, 128'hffff0000000000000000000000000000);
    step("CFB16 dec 4", 1'b1, M_CFB, 4'd4, 1'b1, IV, 128'h63320000000000000000000000000000, 128'h9f960000000000000000000000000000, 128'hffff0000000000000000000000000000);
    step("CFB16 dec 5", 1'b1, M_CFB, 4'd4, 1'b1, IV, 128'hce220000000000000000000000000000, 128'he93d0000000000000000000000000000, 128'hffff0000000000000000000000000000);
    step("CFB16 dec 6", 1'b1, M_CFB, 4'd4, 1'b1, IV, 128'h8e5b0000000000000000000000000000, 128'h7e110000000000000000000000000000, 128'hffff0000000000000000000000000000);
    step("CFB16 dec 7", 1'b1, M_CFB, 4'd4, 1'b1, IV, 128'h81310000000000000000000000000000, 128'h73930000000000000000000000000000, 128'hffff0000000000000000000000000000);
    step("CFB16 dec 8", 1'b1, M_CFB, 4'd4, 1'b1, IV, 128'ha24a0000000000000000000000000000, 128'h172a0000000000000000000000000000, 128'hffff0000000000000000000000000000);
    //CFB32 (reference model)
    new_stream;
    step("CFB32 dec 1", 1'b1, M_CFB, 4'd5, 1'b1, IV, 128'h3b3fd92e000000000000000000000000, 128'h6bc1bee2000000000000000000000000, 128'hffffffff000000000000000000000000);
    step("CFB32 dec 2", 1'b1, M_CFB, 4'd5, 1'b1, IV, 128'he12c0a7c000000000000000000000000, 128'h2e409f96000000000000000000000000, 128'hffffffff000000000000000000000000);
    step("CFB32 dec 3", 1'b1, M_CFB, 4'd5, 1'b1, IV, 128'h7f428924000000000000000000000000, 128'he93d7e11000000000000000000000000, 128'hffffffff000000000000000000000000);
    step("CFB32 dec 4", 1'b1, M_CFB, 4'd5, 1'b1, IV, 128'hfa1aedc3000000000000000000000000, 128'h7393172a000000000000000000000000, 128'hffffffff000000000000000000000000);
    //CFB64 (reference model)
    new_stream;
    step("CFB64 dec 1", 1'b1, M_CFB, 4'd6, 1'b1, IV, 128'h3b3fd92eb72dad200000000000000000, 128'h6bc1bee22e409f960000000000000000, 128'hffffffffffffffff0000000000000000);
    step("CFB64 dec 2", 1'b1, M_CFB, 4'd6, 1'b1, IV, 128'h764bc8b40ee0de400000000000000000, 128'he93d7e117393172a0000000000000000, 128'hffffffffffffffff0000000000000000);
    step("CFB64 dec 3", 1'b1, M_CFB, 4'd6, 1'b1, IV, 128'hf857ab76f3e7bc330000000000000000, 128'hae2d8a571e03ac9c0000000000000000, 128'hffffffffffffffff0000000000000000);
    step("CFB64 dec 4", 1'b1, M_CFB, 4'd6, 1'b1, IV, 128'h332265ff0594b12e0000000000000000, 128'h9eb76fac45af8e510000000000000000, 128'hffffffffffffffff0000000000000000);
    tick(3);
    report("tb_aes128_cfb_decipher");
  end
  initial begin
    #2000000;
    $display("GLOBAL WATCHDOG");
    $display("TEST_RESULT: FAIL watchdog tb_aes128_cfb_decipher");
    $fatal(1, "watchdog");
  end
endmodule
